/* --------------------------------------------------------------- formatter */
typedef struct Sink {
    FILE *f;
    char *buf;
    size_t cap;
    size_t len;
    int to_file;
} Sink;

static void sink_put(Sink *s, char c)
{
    if (s->to_file) {
        unsigned char ch = (unsigned char)c;
        write(s->f->fd, &ch, 1);
    } else if (s->len + 1 < s->cap) {
        s->buf[s->len] = c;
    }
    s->len++;
}

static int utoa(char *tmp, unsigned long long v, unsigned int base, int upper)
{
    const char *dig = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    int n = 0;
    if (v == 0) { tmp[n++] = '0'; return n; }
    while (v) { tmp[n++] = dig[v % base]; v /= base; }
    return n;
}

static int vformat(Sink *s, const char *fmt, va_list ap)
{
    const char *p = fmt;
    while (*p) {
        if (*p != '%') { sink_put(s, *p++); continue; }
        p++;
        if (*p == '%') { sink_put(s, '%'); p++; continue; }
        {
            int left = 0, zero = 0, plus = 0, space = 0, alt = 0, done = 0;
            int width = 0, prec = -1, lng = 0;
            char tmp[72];
            int tlen = 0;
            const char *prefix = "";
            int prefixlen = 0;
            while (!done) {
                switch (*p) {
                case '-': left = 1; p++; break;
                case '0': zero = 1; p++; break;
                case '+': plus = 1; p++; break;
                case ' ': space = 1; p++; break;
                case '#': alt = 1; p++; break;
                default: done = 1; break;
                }
            }
            if (*p == '*') { width = va_arg(ap, int); if (width < 0) { left = 1; width = -width; } p++; }
            else while (*p >= '0' && *p <= '9') { width = width * 10 + (*p - '0'); p++; }
            if (*p == '.') {
                p++;
                prec = 0;
                if (*p == '*') { prec = va_arg(ap, int); p++; }
                else while (*p >= '0' && *p <= '9') { prec = prec * 10 + (*p - '0'); p++; }
            }
            if (*p == 'l') { lng = 1; p++; if (*p == 'l') { lng = 2; p++; } }
            else if (*p == 'h') { p++; if (*p == 'h') p++; }
            else if (*p == 'z' || *p == 't' || *p == 'j') { lng = 1; p++; }
            {
                char conv = *p ? *p++ : 0;
                char pad = zero && !left ? '0' : ' ';
                int fd = 0;
                switch (conv) {
                case 'd': case 'i': {
                    long long v;
                    unsigned long long uv;
                    int neg;
                    if (lng == 2) v = va_arg(ap, long long);
                    else if (lng == 1) v = va_arg(ap, long);
                    else v = va_arg(ap, int);
                    neg = v < 0;
                    uv = neg ? (unsigned long long)(-(v + 1)) + 1 : (unsigned long long)v;
                    tlen = utoa(tmp, uv, 10, 0);
                    if (neg) { prefix = "-"; prefixlen = 1; }
                    else if (plus) { prefix = "+"; prefixlen = 1; }
                    else if (space) { prefix = " "; prefixlen = 1; }
                    fd = 1;
                    break;
                }
                case 'u': case 'x': case 'X': case 'o': {
                    unsigned long long uv;
                    if (lng == 2) uv = va_arg(ap, unsigned long long);
                    else if (lng == 1) uv = va_arg(ap, unsigned long);
                    else uv = va_arg(ap, unsigned int);
                    if (conv == 'u') tlen = utoa(tmp, uv, 10, 0);
                    else if (conv == 'o') tlen = utoa(tmp, uv, 8, 0);
                    else tlen = utoa(tmp, uv, 16, conv == 'X');
                    if (alt && conv == 'x' && uv) { prefix = "0x"; prefixlen = 2; }
                    if (alt && conv == 'X' && uv) { prefix = "0X"; prefixlen = 2; }
                    fd = 1;
                    break;
                }
                case 'p': {
                    unsigned long uv = (unsigned long)(uintptr_t)va_arg(ap, void *);
                    tmp[tlen++] = 'x';
                    tlen += utoa(tmp + tlen, uv, 16, 0);
                    /* reverse the hex digits after the 'x' */
                    {
                        int a = 1, b = tlen - 1;
                        while (a < b) { char c = tmp[a]; tmp[a] = tmp[b]; tmp[b] = c; a++; b--; }
                    }
                    /* now tmp = "0x" + digits */
                    /* fix ordering: construct properly */
                    {
                        char h[32]; int hn = utoa(h, uv, 16, 0); int i;
                        tmp[0] = '0'; tmp[1] = 'x';
                        for (i = 0; i < hn; i++) tmp[2 + i] = h[hn - 1 - i];
                        tlen = hn + 2;
                    }
                    fd = 1;
                    break;
                }
                case 'c': {
                    tmp[0] = (char)va_arg(ap, int);
                    tlen = 1; fd = 1;
                    break;
                }
                case 's': {
                    const char *str = va_arg(ap, const char *);
                    int n;
                    if (!str) str = "(null)";
                    n = (int)strlen(str);
                    if (prec >= 0 && n > prec) n = prec;
                    tlen = n;
                    {
                        int padn = width - tlen;
                        if (!left) while (padn-- > 0) sink_put(s, ' ');
                        for (n = 0; n < tlen; n++) sink_put(s, str[n]);
                        if (left) while (padn-- > 0) sink_put(s, ' ');
                    }
                    continue;
                }
                case 'f': case 'F': {
                    double v = va_arg(ap, double);
                    unsigned long long ip, fv = 0;
                    int neg = v < 0;
                    int i, pr = (prec < 0) ? 6 : prec;
                    double av = neg ? -v : v;
                    static const unsigned long long p10[10] = {
                        1ULL, 10ULL, 100ULL, 1000ULL, 10000ULL, 100000ULL,
                        1000000ULL, 10000000ULL, 100000000ULL, 1000000000ULL
                    };
                    if (pr > 9) pr = 9;
                    ip = (unsigned long long)av;
                    {
                        double frac = av - (double)ip;
                        double scaled = frac * (double)p10[pr];
                        fv = (unsigned long long)(scaled + 0.5);
                        if (fv >= p10[pr]) { fv -= p10[pr]; ip++; }
                    }
                    tlen = utoa(tmp, ip, 10, 0);
                    if (pr > 0) {
                        tmp[tlen++] = '.';
                        {
                            char ft[16];
                            int fn = utoa(ft, fv, 10, 0);
                            while (fn < pr) ft[fn++] = '0';
                            for (i = 0; i < pr; i++) tmp[tlen++] = ft[pr - 1 - i];
                        }
                    }
                    if (neg) { prefix = "-"; prefixlen = 1; }
                    else if (plus) { prefix = "+"; prefixlen = 1; }
                    else if (space) { prefix = " "; prefixlen = 1; }
                    fd = 1;
                    break;
                }
                case 'n': {
                    int *ip = va_arg(ap, int *);
                    if (ip) *ip = (int)s->len;
                    continue;
                }
                default:
                    sink_put(s, '%');
                    if (conv) sink_put(s, conv);
                    continue;
                }
                if (fd) {
                    int total = tlen + prefixlen;
                    int padn = width - total;
                    int i;
                    if (!left) {
                        if (pad == '0' && prefixlen) {
                            for (i = 0; i < prefixlen; i++) sink_put(s, prefix[i]);
                            while (padn-- > 0) sink_put(s, '0');
                        } else {
                            while (padn-- > 0) sink_put(s, pad);
                            for (i = 0; i < prefixlen; i++) sink_put(s, prefix[i]);
                        }
                    } else {
                        for (i = 0; i < prefixlen; i++) sink_put(s, prefix[i]);
                    }
                    /* integer digits in tmp are reversed */
                    if (conv == 's' || conv == 'c') {
                        for (i = 0; i < tlen; i++) sink_put(s, tmp[i]);
                    } else {
                        for (i = tlen - 1; i >= 0; i--) sink_put(s, tmp[i]);
                    }
                    if (left) while (padn-- > 0) sink_put(s, ' ');
                }
            }
        }
    }
    return (int)s->len;
}

int vsnprintf(char *buf, size_t n, const char *fmt, va_list ap)
{
    Sink s;
    int r;
    s.f = 0; s.buf = buf; s.cap = n; s.len = 0; s.to_file = 0;
    r = vformat(&s, fmt, ap);
    if (n) buf[s.len < n ? s.len : n - 1] = 0;
    return r;
}

int vsprintf(char *buf, const char *fmt, va_list ap)
{
