}
double fmod(double x, double y)
{
    long long q;
    if (y == 0) return 0;
    q = (long long)(x / y);
    return x - (double)q * y;
}
#define MINI_PI 3.14159265358979323846
double sqrt(double x)
{
    double g;
    int i;
    if (x <= 0) return 0;
    g = x > 1 ? x : 1;
    for (i = 0; i < 40; i++) g = 0.5 * (g + x / g);
    return g;
}
double sin(double x)
{
    double term, sum;
    int i;
    x = fmod(x, 2 * MINI_PI);
    if (x > MINI_PI) x -= 2 * MINI_PI;
    if (x < -MINI_PI) x += 2 * MINI_PI;
    sum = x; term = x;
    for (i = 1; i < 12; i++) {
        term *= -x * x / ((2 * i) * (2 * i + 1));
        sum += term;
    }
    return sum;
}
