/* atexit */
static void (*s_atexit[64])(void);
static int s_atexit_n;
int atexit(void (*fn)(void))
{
    if (s_atexit_n >= 64) return -1;
    s_atexit[s_atexit_n++] = fn;
    return 0;
}

void exit(int status)
{
    while (s_atexit_n > 0) s_atexit[--s_atexit_n]();
    fflush(stdout);
    fflush(stderr);
    (void)status;
    /* No exit syscall in vm.js: stop the guest. */
    __asm__ volatile("break 0");
    for (;;) ;
}

void _exit(int status) { (void)status; __asm__ volatile("break 0"); for (;;) ; }
