}
double sin(double x)
{
    double term, sum;
    int i;
    x = fmod(x, 2 * MINI_PI);
    if (x > MINI_PI) x -= 2 * MINI_PI;
    if (x < -MINI_PI) x += 2 * MINI_PI;
