/* ---------------------------------------------------------------- syscalls */
/* Syscall numbering used by vm.js (not the Linux/MIPS one). */
#define SYS_read   0
#define SYS_write  1
#define SYS_open   2
#define SYS_close  3
#define SYS_lseek  8

static long m_sys(long n, long a, long b, long c)
{
    register long v0 __asm__("$2") = n;
    register long a0 __asm__("$4") = a;
    register long a1 __asm__("$5") = b;
    register long a2 __asm__("$6") = c;
    __asm__ volatile("syscall"
                     : "+r"(v0)
                     : "r"(a0), "r"(a1), "r"(a2)
                     : "memory");
    return v0;
}

ssize_t read(int fd, void *buf, size_t n)  { return m_sys(SYS_read, fd, (long)buf, n); }
ssize_t write(int fd, const void *buf, size_t n) { return m_sys(SYS_write, fd, (long)buf, n); }
int close(int fd) { return m_sys(SYS_close, fd, 0, 0); }
