/* -------------------------------------------------------------- malloc/free */
#define HEAP_SIZE (64u * 1024u * 1024u)
static unsigned char s_heap[HEAP_SIZE] __attribute__((aligned(8)));

typedef struct Block {
    size_t size;            /* payload size */
    struct Block *next;     /* next free block, sorted by address */
    int free;
} Block;

#define BLK_HDR 12
static Block *s_freelist;
static int s_heap_init;

static void heap_init(void)
{
    s_freelist = (Block *)s_heap;
    s_freelist->size = HEAP_SIZE - BLK_HDR;
    s_freelist->next = 0;
    s_freelist->free = 1;
    s_heap_init = 1;
}

void *malloc(size_t n)
{
    Block *b, *prev;
    size_t need;
    if (!s_heap_init) heap_init();
    if (n == 0) n = 1;
    need = (n + 7u) & ~7u;
    prev = 0;
    for (b = s_freelist; b; prev = b, b = b->next) {
        if (b->size >= need) {
            if (b->size >= need + BLK_HDR + 16) {
                Block *nb = (Block *)((unsigned char *)b + BLK_HDR + need);
                nb->size = b->size - need - BLK_HDR;
                nb->next = b->next;
                nb->free = 1;
                b->size = need;
                b->next = nb;
            }
            if (prev) prev->next = b->next;
            else s_freelist = b->next;
            b->free = 0;
            return (unsigned char *)b + BLK_HDR;
        }
    }
    return 0;
}

void free(void *p)
{
    Block *b, *cur, *prev;
    if (!p) return;
    b = (Block *)((unsigned char *)p - BLK_HDR);
    b->free = 1;
    /* insert sorted by address, coalescing */
    prev = 0; cur = s_freelist;
    while (cur && cur < b) { prev = cur; cur = cur->next; }
    b->next = cur;
    if (prev) prev->next = b; else s_freelist = b;
    if (b->next && (unsigned char *)b + BLK_HDR + b->size == (unsigned char *)b->next) {
        b->size += BLK_HDR + b->next->size;
        b->next = b->next->next;
    }
    if (prev && (unsigned char *)prev + BLK_HDR + prev->size == (unsigned char *)b) {
        prev->size += BLK_HDR + b->size;
        prev->next = b->next;
    }
}

void *calloc(size_t n, size_t size)
{
    size_t total = n * size;
    void *p = malloc(total);
    if (p) memset(p, 0, total);
    return p;
}

void *realloc(void *p, size_t n)
{
    Block *b;
    void *q;
    if (!p) return malloc(n);
    if (!n) { free(p); return 0; }
    b = (Block *)((unsigned char *)p - BLK_HDR);
    if (b->size >= n) return p;
    q = malloc(n);
    if (!q) return 0;
    memcpy(q, p, b->size);
    free(p);
    return q;
}

/* ------------------------------------------------------------------- stdio */
struct _MINI_FILE {
    int fd;
    int eof;
    int err;
    int used;
};

static FILE f_stdin  = { 0, 0, 0, 1 };
static FILE f_stdout = { 1, 0, 0, 1 };
static FILE f_stderr = { 2, 0, 0, 1 };
FILE *stdin = &f_stdin;
FILE *stdout = &f_stdout;
FILE *stderr = &f_stderr;

FILE *fdopen(int fd, const char *mode)
{
    FILE *f = malloc(sizeof(FILE));
    (void)mode;
    if (!f) return 0;
    f->fd = fd; f->eof = 0; f->err = 0; f->used = 1;
    return f;
}

FILE *fopen(const char *path, const char *mode)
{
    int flags;
    int fd;
    if (!mode || !*mode) return 0;
    if (mode[0] == 'r')
        flags = (strchr(mode, '+') ? O_RDWR : O_RDONLY);
    else if (mode[0] == 'w')
        flags = (strchr(mode, '+') ? (O_RDWR | O_CREAT | O_TRUNC)
                                   : (O_WRONLY | O_CREAT | O_TRUNC));
    else if (mode[0] == 'a')
        flags = (strchr(mode, '+') ? (O_RDWR | O_CREAT | O_APPEND)
                                   : (O_WRONLY | O_CREAT | O_APPEND));
    else return 0;
    fd = (int)m_sys(SYS_open, (long)path, flags, 0644);
    if (fd < 0) return 0;
    return fdopen(fd, mode);
}

int fclose(FILE *f)
{
    if (!f) return EOF;
    if (f->fd >= 0) close(f->fd);
    if (f->used && f != &f_stdin && f != &f_stdout && f != &f_stderr)
