char *strdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}
char *strerror(int e) { (void)e; return "error"; }

/* -------------------------------------------------------------- malloc/free */
#define HEAP_SIZE (64u * 1024u * 1024u)
static unsigned char s_heap[HEAP_SIZE] __attribute__((aligned(8)));

typedef struct Block {
    size_t size;            /* payload size */
    struct Block *next;     /* next free block, sorted by address */
    int free;
} Block;

#define BLK_HDR 12
static Block *s_freelist;
static int s_heap_init;

static void heap_init(void)
{
    s_freelist = (Block *)s_heap;
    s_freelist->size = HEAP_SIZE - BLK_HDR;
    s_freelist->next = 0;
    s_freelist->free = 1;
    s_heap_init = 1;
}

void *malloc(size_t n)
{
    Block *b, *prev;
    size_t need;
    if (!s_heap_init) heap_init();
    if (n == 0) n = 1;
    need = (n + 7u) & ~7u;
    prev = 0;
    for (b = s_freelist; b; prev = b, b = b->next) {
        if (b->size >= need) {
            if (b->size >= need + BLK_HDR + 16) {
                Block *nb = (Block *)((unsigned char *)b + BLK_HDR + need);
                nb->size = b->size - need - BLK_HDR;
                nb->next = b->next;
                nb->free = 1;
                b->size = need;
                b->next = nb;
            }
            if (prev) prev->next = b->next;
            else s_freelist = b->next;
            b->free = 0;
            return (unsigned char *)b + BLK_HDR;
        }
    }
    return 0;
}

void free(void *p)
{
    Block *b, *cur, *prev;
    if (!p) return;
    b = (Block *)((unsigned char *)p - BLK_HDR);
    b->free = 1;
    /* insert sorted by address, coalescing */
    prev = 0; cur = s_freelist;
    while (cur && cur < b) { prev = cur; cur = cur->next; }
    b->next = cur;
    if (prev) prev->next = b; else s_freelist = b;
    if (b->next && (unsigned char *)b + BLK_HDR + b->size == (unsigned char *)b->next) {
        b->size += BLK_HDR + b->next->size;
        b->next = b->next->next;
    }
    if (prev && (unsigned char *)prev + BLK_HDR + prev->size == (unsigned char *)b) {
        prev->size += BLK_HDR + b->size;
        prev->next = b->next;
    }
}

void *calloc(size_t n, size_t size)
{
    size_t total = n * size;
    void *p = malloc(total);
    if (p) memset(p, 0, total);
    return p;
}

void *realloc(void *p, size_t n)
{
    Block *b;
    void *q;
    if (!p) return malloc(n);
    if (!n) { free(p); return 0; }
    b = (Block *)((unsigned char *)p - BLK_HDR);
    if (b->size >= n) return p;
    q = malloc(n);
    if (!q) return 0;
    memcpy(q, p, b->size);
    free(p);
    return q;
}

/* ------------------------------------------------------------------- stdio */
struct _MINI_FILE {
    int fd;
    int eof;
    int err;
    int used;
};

static FILE f_stdin  = { 0, 0, 0, 1 };
static FILE f_stdout = { 1, 0, 0, 1 };
static FILE f_stderr = { 2, 0, 0, 1 };
FILE *stdin = &f_stdin;
FILE *stdout = &f_stdout;
FILE *stderr = &f_stderr;

FILE *fdopen(int fd, const char *mode)
{
    FILE *f = malloc(sizeof(FILE));
    (void)mode;
    if (!f) return 0;
    f->fd = fd; f->eof = 0; f->err = 0; f->used = 1;
    return f;
}

FILE *fopen(const char *path, const char *mode)
{
    int flags;
    int fd;
    if (!mode || !*mode) return 0;
    if (mode[0] == 'r')
        flags = (strchr(mode, '+') ? O_RDWR : O_RDONLY);
    else if (mode[0] == 'w')
        flags = (strchr(mode, '+') ? (O_RDWR | O_CREAT | O_TRUNC)
                                   : (O_WRONLY | O_CREAT | O_TRUNC));
    else if (mode[0] == 'a')
        flags = (strchr(mode, '+') ? (O_RDWR | O_CREAT | O_APPEND)
                                   : (O_WRONLY | O_CREAT | O_APPEND));
    else return 0;
    fd = (int)m_sys(SYS_open, (long)path, flags, 0644);
    if (fd < 0) return 0;
    return fdopen(fd, mode);
}

int fclose(FILE *f)
{
    if (!f) return EOF;
    if (f->fd >= 0) close(f->fd);
    if (f->used && f != &f_stdin && f != &f_stdout && f != &f_stderr)
        free(f);
    return 0;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *f)
{
    size_t want = size * nmemb, got = 0;
    unsigned char *p = ptr;
    if (!f || !want) return 0;
    while (got < want) {
        ssize_t r = read(f->fd, p + got, want - got);
        if (r <= 0) { if (r == 0) f->eof = 1; else f->err = 1; break; }
        got += (size_t)r;
    }
    return size ? got / size : 0;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *f)
{
    size_t want = size * nmemb, put = 0;
    const unsigned char *p = ptr;
    if (!f || !want) return 0;
    while (put < want) {
        ssize_t r = write(f->fd, p + put, want - put);
        if (r <= 0) { f->err = 1; break; }
        put += (size_t)r;
    }
    return size ? put / size : 0;
}

int fseek(FILE *f, long offset, int whence)
{
    if (!f) return -1;
    f->eof = 0;
    return lseek(f->fd, offset, whence) < 0 ? -1 : 0;
}

long ftell(FILE *f) { return f ? (long)lseek(f->fd, 0, SEEK_CUR) : -1; }
void rewind(FILE *f) { if (f) { fseek(f, 0, SEEK_SET); f->err = 0; } }
int fflush(FILE *f) { (void)f; return 0; }
int feof(FILE *f) { return f ? f->eof : 0; }
int ferror(FILE *f) { return f ? f->err : 0; }
void clearerr(FILE *f) { if (f) { f->eof = 0; f->err = 0; } }
int fileno(FILE *f) { return f ? f->fd : -1; }

int fgetc(FILE *f)
{
    unsigned char c;
    if (!f) return EOF;
    if (read(f->fd, &c, 1) != 1) { f->eof = 1; return EOF; }
    return c;
}
int getc(FILE *f) { return fgetc(f); }
int getchar(void) { return fgetc(stdin); }
int ungetc(int c, FILE *f) { (void)c; (void)f; return EOF; }

char *fgets(char *s, int n, FILE *f)
{
    int i = 0;
    if (!f || n <= 0) return 0;
    while (i < n - 1) {
        int c = fgetc(f);
        if (c == EOF) { if (i == 0) return 0; break; }
        s[i++] = (char)c;
        if (c == '\n') break;
    }
    s[i] = 0;
    return s;
}

int fputc(int c, FILE *f)
{
    unsigned char ch = (unsigned char)c;
    if (!f) return EOF;
    return write(f->fd, &ch, 1) == 1 ? ch : EOF;
}
int putc(int c, FILE *f) { return fputc(c, f); }
int putchar(int c) { return fputc(c, stdout); }

int fputs(const char *s, FILE *f)
{
    size_t n = strlen(s);
    return fwrite(s, 1, n, f) == n ? 0 : EOF;
}
int puts(const char *s)
{
    if (fputs(s, stdout) == EOF) return EOF;
    if (fputc('\n', stdout) == EOF) return EOF;
    return 0;
}

/* --------------------------------------------------------------- formatter */
typedef struct Sink {
    FILE *f;
    char *buf;
    size_t cap;
    size_t len;
    int to_file;
} Sink;

static void sink_put(Sink *s, char c)
{
    if (s->to_file) {
        unsigned char ch = (unsigned char)c;
        write(s->f->fd, &ch, 1);
    } else if (s->len + 1 < s->cap) {
        s->buf[s->len] = c;
    }
    s->len++;
}

static int utoa(char *tmp, unsigned long long v, unsigned int base, int upper)
{
    const char *dig = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    int n = 0;
    if (v == 0) { tmp[n++] = '0'; return n; }
    while (v) { tmp[n++] = dig[v % base]; v /= base; }
    return n;
}

static int vformat(Sink *s, const char *fmt, va_list ap)
{
    const char *p = fmt;
    while (*p) {
        if (*p != '%') { sink_put(s, *p++); continue; }
        p++;
        if (*p == '%') { sink_put(s, '%'); p++; continue; }
        {
            int left = 0, zero = 0, plus = 0, space = 0, alt = 0, done = 0;
            int width = 0, prec = -1, lng = 0;
            char tmp[72];
            int tlen = 0;
            const char *prefix = "";
            int prefixlen = 0;
            while (!done) {
                switch (*p) {
                case '-': left = 1; p++; break;
                case '0': zero = 1; p++; break;
                case '+': plus = 1; p++; break;
                case ' ': space = 1; p++; break;
                case '#': alt = 1; p++; break;
                default: done = 1; break;
                }
            }
            if (*p == '*') { width = va_arg(ap, int); if (width < 0) { left = 1; width = -width; } p++; }
            else while (*p >= '0' && *p <= '9') { width = width * 10 + (*p - '0'); p++; }
            if (*p == '.') {
                p++;
                prec = 0;
                if (*p == '*') { prec = va_arg(ap, int); p++; }
                else while (*p >= '0' && *p <= '9') { prec = prec * 10 + (*p - '0'); p++; }
            }
            if (*p == 'l') { lng = 1; p++; if (*p == 'l') { lng = 2; p++; } }
            else if (*p == 'h') { p++; if (*p == 'h') p++; }
            else if (*p == 'z' || *p == 't' || *p == 'j') { lng = 1; p++; }
            {
                char conv = *p ? *p++ : 0;
                char pad = zero && !left ? '0' : ' ';
                int fd = 0;
                int reverse = 1;
                switch (conv) {
                case 'd': case 'i': {
                    long long v;
                    unsigned long long uv;
                    int neg;
                    if (lng == 2) v = va_arg(ap, long long);
                    else if (lng == 1) v = va_arg(ap, long);
                    else v = va_arg(ap, int);
                    neg = v < 0;
                    uv = neg ? (unsigned long long)(-(v + 1)) + 1 : (unsigned long long)v;
                    tlen = utoa(tmp, uv, 10, 0);
                    if (neg) { prefix = "-"; prefixlen = 1; }
                    else if (plus) { prefix = "+"; prefixlen = 1; }
                    else if (space) { prefix = " "; prefixlen = 1; }
                    fd = 1;
                    break;
                }
                case 'u': case 'x': case 'X': case 'o': {
                    unsigned long long uv;
                    if (lng == 2) uv = va_arg(ap, unsigned long long);
                    else if (lng == 1) uv = va_arg(ap, unsigned long);
                    else uv = va_arg(ap, unsigned int);
                    if (conv == 'u') tlen = utoa(tmp, uv, 10, 0);
                    else if (conv == 'o') tlen = utoa(tmp, uv, 8, 0);
                    else tlen = utoa(tmp, uv, 16, conv == 'X');
                    if (alt && conv == 'x' && uv) { prefix = "0x"; prefixlen = 2; }
                    if (alt && conv == 'X' && uv) { prefix = "0X"; prefixlen = 2; }
                    fd = 1;
                    break;
                }
                case 'p': {
                    unsigned long uv = (unsigned long)(uintptr_t)va_arg(ap, void *);
                    char h[32]; int hn = utoa(h, uv, 16, 0); int i;
                    tmp[0] = '0'; tmp[1] = 'x';
                    for (i = 0; i < hn; i++) tmp[2 + i] = h[hn - 1 - i];
                    tlen = hn + 2;
                    reverse = 0;
                    fd = 1;
                    break;
                }
                case 'c': {
                    tmp[0] = (char)va_arg(ap, int);
                    tlen = 1; fd = 1;
                    break;
                }
                case 's': {
                    const char *str = va_arg(ap, const char *);
                    int n;
                    if (!str) str = "(null)";
                    n = (int)strlen(str);
                    if (prec >= 0 && n > prec) n = prec;
                    tlen = n;
                    {
                        int padn = width - tlen;
                        if (!left) while (padn-- > 0) sink_put(s, ' ');
                        for (n = 0; n < tlen; n++) sink_put(s, str[n]);
                        if (left) while (padn-- > 0) sink_put(s, ' ');
                    }
                    continue;
                }
                case 'f': case 'F': {
                    double v = va_arg(ap, double);
                    unsigned long long ip, fv = 0;
                    int neg = v < 0;
                    int i, pr = (prec < 0) ? 6 : prec;
                    double av = neg ? -v : v;
                    static const unsigned long long p10[10] = {
                        1ULL, 10ULL, 100ULL, 1000ULL, 10000ULL, 100000ULL,
                        1000000ULL, 10000000ULL, 100000000ULL, 1000000000ULL
                    };
                    if (pr > 9) pr = 9;
                    ip = (unsigned long long)av;
                    {
                        double frac = av - (double)ip;
                        double scaled = frac * (double)p10[pr];
                        fv = (unsigned long long)(scaled + 0.5);
                        if (fv >= p10[pr]) { fv -= p10[pr]; ip++; }
                    }
                    {
                        char ipd[24], ft[16];
                        int ipn = utoa(ipd, ip, 10, 0);
                        int fn = utoa(ft, fv, 10, 0);
                        tlen = 0;
                        for (i = 0; i < ipn; i++) tmp[tlen++] = ipd[ipn - 1 - i];
                        if (pr > 0) {
                            tmp[tlen++] = '.';
                            while (fn < pr) ft[fn++] = '0';
                            for (i = 0; i < pr; i++) tmp[tlen++] = ft[pr - 1 - i];
                        }
                    }
                    reverse = 0;
                    if (neg) { prefix = "-"; prefixlen = 1; }
                    else if (plus) { prefix = "+"; prefixlen = 1; }
                    else if (space) { prefix = " "; prefixlen = 1; }
                    fd = 1;
                    break;
                }
                case 'n': {
                    int *ip = va_arg(ap, int *);
                    if (ip) *ip = (int)s->len;
                    continue;
                }
                default:
                    sink_put(s, '%');
                    if (conv) sink_put(s, conv);
                    continue;
                }
                if (fd) {
                    int total = tlen + prefixlen;
                    int padn = width - total;
                    int i;
                    if (!left) {
                        if (pad == '0' && prefixlen) {
                            for (i = 0; i < prefixlen; i++) sink_put(s, prefix[i]);
                            while (padn-- > 0) sink_put(s, '0');
                        } else {
                            while (padn-- > 0) sink_put(s, pad);
                            for (i = 0; i < prefixlen; i++) sink_put(s, prefix[i]);
                        }
                    } else {
                        for (i = 0; i < prefixlen; i++) sink_put(s, prefix[i]);
                    }
                    /* integer digits in tmp are reversed */
                    if (!reverse) {
                        for (i = 0; i < tlen; i++) sink_put(s, tmp[i]);
                    } else {
                        for (i = tlen - 1; i >= 0; i--) sink_put(s, tmp[i]);
                    }
                    if (left) while (padn-- > 0) sink_put(s, ' ');
                }
            }
        }
    }
    return (int)s->len;
}

int vsnprintf(char *buf, size_t n, const char *fmt, va_list ap)
{
    Sink s;
    int r;
    s.f = 0; s.buf = buf; s.cap = n; s.len = 0; s.to_file = 0;
    r = vformat(&s, fmt, ap);
    if (n) buf[s.len < n ? s.len : n - 1] = 0;
    return r;
}

int vsprintf(char *buf, const char *fmt, va_list ap)
{
    return vsnprintf(buf, 0x7fffffffu, fmt, ap);
}

int vfprintf(FILE *f, const char *fmt, va_list ap)
{
    Sink s;
    s.f = f; s.buf = 0; s.cap = 0; s.len = 0; s.to_file = 1;
    return vformat(&s, fmt, ap);
}

int printf(const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vfprintf(stdout, fmt, ap);
    va_end(ap);
    return r;
}

int fprintf(FILE *f, const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vfprintf(f, fmt, ap);
    va_end(ap);
    return r;
}

int sprintf(char *buf, const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vsprintf(buf, fmt, ap);
    va_end(ap);
    return r;
}

int snprintf(char *buf, size_t n, const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vsnprintf(buf, n, fmt, ap);
    va_end(ap);
    return r;
}

void perror(const char *s)
{
    if (s && *s) { fputs(s, stderr); fputs(": ", stderr); }
    fputs(strerror(errno), stderr);
    fputc('\n', stderr);
}

int sscanf(const char *s, const char *fmt, ...)
{
    va_list ap;
    int assigned = 0;
    const char *p = fmt;
    va_start(ap, fmt);
    while (*p) {
        if (*p == ' ' || *p == '\t') {
            while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
            p++;
            continue;
        }
        if (*p != '%') {
            if (*s != *p) break;
            s++; p++;
            continue;
        }
        p++;
        {
            int suppress = 0, base = 10, lng = 0, isfloat = 0, isstr = 0;
            char conv;
            if (*p == '*') { suppress = 1; p++; }
            while (*p >= '0' && *p <= '9') p++;
            if (*p == 'l') { lng = 1; p++; if (*p == 'l') { lng = 2; p++; } }
            conv = *p ? *p++ : 0;
            while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
            if (conv == 'x' || conv == 'X') base = 16;
            else if (conv == 'o') base = 8;
            else if (conv == 'i') base = 0;
            else if (conv == 'f' || conv == 'e' || conv == 'g') isfloat = 1;
            else if (conv == 's' || conv == 'c') isstr = 1;
            if (isstr) {
                if (conv == 's') {
                    char *out = suppress ? 0 : va_arg(ap, char *);
                    int n = 0;
                    while (*s && !(*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) {
                        if (out) out[n] = *s;
                        n++; s++;
                    }
                    if (out) out[n] = 0;
                    if (n) assigned++;
                } else {
                    char *out = suppress ? 0 : va_arg(ap, char *);
                    if (*s) { if (out) *out = *s; s++; assigned++; }
                }
            } else if (isfloat) {
                char *end;
                double v = strtod(s, &end);
                if (end == s) break;
                s = end;
                if (!suppress) {
                    if (lng) *va_arg(ap, double *) = v;
                    else *va_arg(ap, float *) = (float)v;
                    assigned++;
                }
            } else {
                char *end;
                long v = strtol(s, &end, base);
                if (end == s) break;
                s = end;
                if (!suppress) {
                    if (lng == 2) *va_arg(ap, long long *) = (long long)v;
                    else if (lng == 1) *va_arg(ap, long *) = v;
                    else *va_arg(ap, int *) = (int)v;
                    assigned++;
                }
            }
        }
    }
    va_end(ap);
    return assigned;
}

/* ------------------------------------------------------------ stdlib misc */
int atoi(const char *s) { return (int)strtol(s, 0, 10); }
long atol(const char *s) { return strtol(s, 0, 10); }

long strtol(const char *s, char **end, int base)
{
    unsigned long v = 0;
    int neg = 0;
    const char *p = s;
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    if (*p == '-' || *p == '+') { neg = (*p == '-'); p++; }
    if ((base == 0 || base == 16) && p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
        base = 16; p += 2;
    } else if (base == 0 && p[0] == '0') {
        base = 8;
    } else if (base == 0) base = 10;
    while (*p) {
        int d;
        if (*p >= '0' && *p <= '9') d = *p - '0';
        else if (*p >= 'a' && *p <= 'z') d = *p - 'a' + 10;
        else if (*p >= 'A' && *p <= 'Z') d = *p - 'A' + 10;
        else break;
        if (d >= base) break;
        v = v * (unsigned)base + (unsigned)d;
        p++;
    }
    if (end) *end = (char *)p;
    return neg ? -(long)v : (long)v;
}

unsigned long strtoul(const char *s, char **end, int base)
{
    return (unsigned long)strtol(s, end, base);
}

double strtod(const char *s, char **end)
{
    double v = 0.0;
    int neg = 0, any = 0;
    const char *p = s;
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    if (*p == '-' || *p == '+') { neg = (*p == '-'); p++; }
    while (*p >= '0' && *p <= '9') { v = v * 10.0 + (double)(*p - '0'); p++; any = 1; }
    if (*p == '.') {
        double f = 0.1;
        p++;
        while (*p >= '0' && *p <= '9') { v += (*p - '0') * f; f *= 0.1; p++; any = 1; }
    }
    if (any && (*p == 'e' || *p == 'E')) {
        int en = 0, es = 1;
        const char *q = p + 1;
        if (*q == '-' || *q == '+') { es = (*q == '-') ? -1 : 1; q++; }
        while (*q >= '0' && *q <= '9') { en = en * 10 + (*q - '0'); q++; }
        while (en--) v = es < 0 ? v / 10.0 : v * 10.0;
        p = q;
    }
    if (end) *end = (char *)p;
    return neg ? -v : v;
}

double atof(const char *s) { return strtod(s, 0); }
int abs(int x) { return x < 0 ? -x : x; }
long labs(long x) { return x < 0 ? -x : x; }

char *getenv(const char *name) { (void)name; return 0; }
int system(const char *cmd) { (void)cmd; return -1; }

/* atexit */
static void (*s_atexit[64])(void);
static int s_atexit_n;
int atexit(void (*fn)(void))
{
    if (s_atexit_n >= 64) return -1;
    s_atexit[s_atexit_n++] = fn;
    return 0;
}

void exit(int status)
{
    while (s_atexit_n > 0) s_atexit[--s_atexit_n]();
    fflush(stdout);
    fflush(stderr);
    (void)status;
    /* No exit syscall in vm.js: stop the guest. */
    __asm__ volatile("break 0");
    for (;;) ;
}

void _exit(int status) { (void)status; __asm__ volatile("break 0"); for (;;) ; }
void abort(void) { __asm__ volatile("break 0"); for (;;) ; }
void __assert_fail(const char *e, const char *f, unsigned int l, const char *fn)
{
