    if ((x.u & 0x7fffffffffffffffULL) == 0) return b;
    if ((y.u & 0x7fffffffffffffffULL) == 0) return a;
    unpackd(x.u, &sa, &ea, &ma);
    unpackd(y.u, &sb, &eb, &mb);
