    if (!eb) { mb = 0; }
    if (ma == 0) return b;
    if (mb == 0) return a;
    /* work with three guard bits */
    ma <<= 3;
    mb <<= 3;
    if (ea > eb) {
        diff = ea - eb;
        if (diff > 63) return a;
        mb = (mb >> diff) | ((mb & ((1ULL << diff) - 1)) ? 1 : 0);
        e = ea;
        sign = sa;
