    x.d = a; y.d = b;
    sa = (int)(x.u >> 63); sb = (int)(y.u >> 63);
    if ((x.u & 0x7fffffffffffffffULL) == 0) {
        if ((y.u & 0x7fffffffffffffffULL) == 0) return 0;
        return sb ? 1 : -1;
    }
    if ((y.u & 0x7fffffffffffffffULL) == 0) return sa ? -1 : 1;
    if (sa != sb) return sa ? -1 : 1;
    unpackd(x.u, &sa, &ea, &ma);
    unpackd(y.u, &sb, &eb, &mb);
    {
        int c;
        if (ea != eb) c = (ea < eb) ? -1 : 1;
        else if (ma != mb) c = (ma < mb) ? -1 : 1;
